//! Control Center / popup icon set: original vector icons drawn as Direct2D path geometry on one
//! 24-unit optical grid with a single stroke weight, round caps and joins (an SF-Symbols-like
//! style, drawn from scratch). Path data is generated by `tools/gen_icons.py`.
use windows::core::Result;

use super::dock::RectF;
use super::renderer::Renderer;
use super::svgpath;

/// How a path is painted.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum K {
    /// Stroked with `STROKE` (grid units), round caps and joins.
    Stroke,
    /// Stroked with `BOLD`: line glyphs that sit next to the filled Wi-Fi fan (Bluetooth,
    /// network, the Wi-Fi slash).
    Bold,
    /// Filled as is.
    Fill,
    /// Filled, then outlined with `ROUND_EDGE` so corners come out softly rounded.
    Round,
}

/// Stroke weight in grid units: 2 DIP when the icon box is 24 DIP, scaling with the size.
pub const STROKE: f32 = 2.0;
/// Bold stroke in grid units, matching the 2.5-unit bands of the filled Wi-Fi fan.
const BOLD: f32 = 2.5;
const ROUND_EDGE: f32 = 1.6;
const GRID: f32 = 24.0;
/// Opacity of unlit Wi-Fi bands.
const DIM: f32 = 0.3;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Icon {
    /// `bars` 0..=3 lit arcs (dot always lit); `off` dims everything and adds a slash.
    Wifi { bars: u8, off: bool },
    Bluetooth,
    Network,
    Moon,
    /// `waves` 0..=3; `muted` replaces the waves with a cross.
    Speaker { waves: u8, muted: bool },
    Display,
    Calculator,
    Camera,
    Timer,
    Gear,
    SunMin,
    SunMax,
    Prev,
    Pause,
    Play,
    Next,
    Chevron,
    /// Left-pointing chevron (sub-page back button).
    Back,
    Music,
    // Edit Controls additions (hand-drawn on the same grid; see the consts at the end).
    Airplane,
    NightLight,
    Focus,
    BatterySaver,
    /// `muted` adds a slash.
    Mic { muted: bool },
    Lock,
    Sleep,
    Clipboard,
    TaskManager,
    Folder,
    Hotspot,
}

impl Icon {
    pub const ALL: [Icon; 34] = [
        Icon::Wifi { bars: 3, off: false },
        Icon::Wifi { bars: 2, off: false },
        Icon::Wifi { bars: 1, off: false },
        Icon::Wifi { bars: 3, off: true },
        Icon::Bluetooth,
        Icon::Network,
        Icon::Moon,
        Icon::Speaker { waves: 3, muted: false },
        Icon::Speaker { waves: 0, muted: false },
        Icon::Speaker { waves: 0, muted: true },
        Icon::Display,
        Icon::Calculator,
        Icon::Camera,
        Icon::Timer,
        Icon::Gear,
        Icon::SunMin,
        Icon::SunMax,
        Icon::Prev,
        Icon::Pause,
        Icon::Play,
        Icon::Next,
        Icon::Music,
        Icon::Airplane,
        Icon::NightLight,
        Icon::Focus,
        Icon::BatterySaver,
        Icon::Mic { muted: false },
        Icon::Mic { muted: true },
        Icon::Lock,
        Icon::Sleep,
        Icon::Clipboard,
        Icon::TaskManager,
        Icon::Folder,
        Icon::Hotspot,
    ];
}

type Part = &'static [(&'static str, K)];

/// The layers of an icon: (paths, opacity factor), plus a horizontal offset in grid units that
/// optically centres asymmetric variants (a speaker without waves).
fn layers(icon: Icon) -> (Vec<(Part, f32)>, f32, f32) {
    match icon {
        Icon::Wifi { bars, off } => {
            let lit = |n: u8| if off || bars < n { DIM } else { 1.0 };
            let mut v: Vec<(Part, f32)> = vec![
                // The wedge is always lit while on (1 bar), then the inner and outer bands.
                (WIFI_DOT, if off { DIM } else { 1.0 }),
                (WIFI_ARC1, lit(2)),
                (WIFI_ARC2, lit(3)),
            ];
            if off {
                v.push((WIFI_SLASH, 1.0));
            }
            // The fan's mass reads low in a round badge: lift it by 0.6 grid units.
            (v, 0.0, -0.6)
        }
        Icon::Speaker { waves, muted } => {
            let mut v: Vec<(Part, f32)> = vec![(SPEAKER, 1.0)];
            let right = if muted {
                v.push((MUTE_X, 1.0));
                21.0
            } else {
                let w = waves.min(3);
                for p in [WAVE1, WAVE2, WAVE3].into_iter().take(w as usize) {
                    v.push((p, 1.0));
                }
                match w {
                    0 => 11.6,
                    1 => 15.6,
                    2 => 18.8,
                    _ => 22.0,
                }
            };
            (v, 12.0 - (2.0 + right) / 2.0, 0.0)
        }
        Icon::Mic { muted } => {
            let mut v: Vec<(Part, f32)> = vec![(MIC, 1.0)];
            if muted {
                v.push((WIFI_SLASH, 1.0));
            }
            (v, 0.0, 0.0)
        }
        other => {
            let p: Part = match other {
                Icon::Airplane => AIRPLANE,
                Icon::NightLight => NIGHT_LIGHT,
                Icon::Focus => FOCUS,
                Icon::BatterySaver => BATTERY_SAVER,
                Icon::Lock => LOCK,
                Icon::Sleep => SLEEP,
                Icon::Clipboard => CLIPBOARD,
                Icon::TaskManager => TASK_MANAGER,
                Icon::Folder => FOLDER,
                Icon::Hotspot => HOTSPOT,
                Icon::Bluetooth => BLUETOOTH,
                Icon::Network => NETWORK,
                Icon::Moon => MOON,
                Icon::Display => DISPLAY,
                Icon::Calculator => CALCULATOR,
                Icon::Camera => CAMERA,
                Icon::Timer => TIMER,
                Icon::Gear => GEAR,
                Icon::SunMin => SUN_MIN,
                Icon::SunMax => SUN_MAX,
                Icon::Prev => PREV,
                Icon::Pause => PAUSE,
                Icon::Play => PLAY,
                Icon::Next => NEXT,
                Icon::Chevron => CHEVRON,
                Icon::Back => BACK,
                _ => MUSIC,
            };
            (vec![(p, 1.0)], 0.0, 0.0)
        }
    }
}

fn fade(rgba: u32, k: f32) -> u32 {
    let a = ((rgba & 0xFF) as f32 * k.clamp(0.0, 1.0)).round() as u32;
    (rgba & !0xFF) | a
}

/// Draws `icon` in a `size` x `size` DIP box centred at (`cx`, `cy`).
pub fn draw(r: &mut Renderer, icon: Icon, cx: f32, cy: f32, size: f32, rgba: u32) -> Result<()> {
    let (layers, dx, dy) = layers(icon);
    let unit = size / GRID;
    let rect = RectF { x: cx - size / 2.0 + dx * unit, y: cy - size / 2.0 + dy * unit, w: size, h: size };
    for (parts, k) in layers {
        let color = fade(rgba, k);
        for &(d, kind) in parts {
            match kind {
                K::Stroke => svgpath::draw_path_round(r, d, rect, GRID, color, Some(STROKE))?,
                K::Bold => svgpath::draw_path_round(r, d, rect, GRID, color, Some(BOLD))?,
                K::Fill => svgpath::draw_path_round(r, d, rect, GRID, color, None)?,
                K::Round => {
                    svgpath::draw_path_round(r, d, rect, GRID, color, None)?;
                    svgpath::draw_path_round(r, d, rect, GRID, color, Some(ROUND_EDGE))?;
                }
            }
        }
    }
    Ok(())
}

/// `draw` centred in `rect`.
pub fn draw_in(r: &mut Renderer, icon: Icon, rect: RectF, size: f32, rgba: u32) -> Result<()> {
    draw(r, icon, rect.x + rect.w / 2.0, rect.y + rect.h / 2.0, size, rgba)
}

